using System;using System.Collections.Generic;using System.Drawing;using System.Drawing.Imaging;using System.IO;using System.Linq;using System.Reflection;using System.Security.Cryptography;using System.Text;using System.Threading;using System.Web.Script.Serialization;using System.Windows.Forms;using UsbRecovery;
public static class UxQualityTests
{
    static int checks;static string root;
    static void Check(bool value,string name){checks++;if(!value)throw new Exception(name);}
    static T Field<T>(object value,string name)where T:class{return value.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(value)as T;}
    static IEnumerable<Control> Children(Control p){foreach(Control c in p.Controls){yield return c;foreach(Control x in Children(c))yield return x;}}
    static void Pump(){for(int i=0;i<8;i++){Application.DoEvents();Thread.Sleep(15);}}
    static void Show(Form form){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);form.ShowInTaskbar=false;form.Show();Pump();}
    static void Shot(Form form,string name){using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(Path.Combine(root,name+".png"),ImageFormat.Png);}}
    static string Hash(string path){using(var stream=File.OpenRead(path))using(var hash=SHA256.Create())return BitConverter.ToString(hash.ComputeHash(stream)).Replace("-","");}
    static RecoveredItem Item(string directory,string name,string category,string method,string quality){string path=Path.Combine(directory,name);return new RecoveredItem{Name=name,Path=name,Extension=Path.GetExtension(name),Category=category,Method=method,Status="Требует проверки",Sha256=Hash(path),Bytes=new FileInfo(path).Length,QualityLabel=quality,IntegrityDetail="Синтетическая проверка; не доказательство исходной полноты",Note="Искусственный образец"};}
    static void SetupUi()
    {
        using(var form=new RecoveryForm(false)){
            Show(form);var settings=Field<RecoverySettingsPanel>(form,"searchSettings");var profile=Field<ComboBox>(form,"profile");Check(!form.ExpertMode&&!settings.Visible&&Field<SurfaceCard>(form,"basicSummary").Height<=164,"basic mode default compact summary");Check(Children(settings).OfType<CheckBox>().Count()==23,"23 expert methods/options");
            foreach(var size in new[]{new Size(850,740),new Size(1040,910),new Size(1280,920)})foreach(bool expert in new[]{false,true}){
                form.ClientSize=size;form.SetExpertMode(expert);Pump();Check(form.Controls[0].Width<=form.ClientSize.Width&&!form.VerticalScroll.Visible,"no whole-window crop/scroll "+size+" expert="+expert);var start=Field<Button>(form,"start");var results=Field<Button>(form,"fileList");Check(form.RectangleToClient(start.RectangleToScreen(start.ClientRectangle)).Bottom<form.ClientSize.Height&&form.RectangleToClient(results.RectangleToScreen(results.ClientRectangle)).Bottom<form.ClientSize.Height,"scan and results visible "+size+" expert="+expert);Check(settings.Visible==expert,"expert visibility "+expert);
            }
            profile.SelectedIndex=4;Check(settings.Selection().MetadataRescue&&settings.Selection().ArchiveMembers&&settings.Selection().FragmentedArchives,"maximum includes independent methods");profile.SelectedIndex=0;Check(!settings.Selection().MetadataRescue&&!settings.Selection().ArchiveMembers&&!settings.Selection().FragmentedArchives,"standard keeps expensive methods optional");form.ClientSize=new Size(1040,910);form.SetExpertMode(false);Pump();Shot(form,"UX-basic");form.SetExpertMode(true);settings.SelectedIndex=2;Pump();Shot(form,"UX-expert");form.ClientSize=new Size(850,740);Pump();Shot(form,"UX-compact");form.Hide();
        }
        using(var hub=new RecoveryHub(false)){Show(hub);Shot(hub,"UX-hub");hub.ClientSize=new Size(1060,760);Pump();var form=Field<RecoveryForm>(hub,"disks");Check(form!=null&&!form.VerticalScroll.Visible,"embedded min hub without outer scrolling");form.SetExpertMode(true);Pump();Shot(hub,"UX-hub-compact");hub.Hide();}
    }
    static string Fixtures()
    {
        string dir=Path.Combine(root,"fixture");Directory.CreateDirectory(dir);var index=new RecoveryFileIndex{Candidates=207};
        using(var image=new Bitmap(120,80)){using(var g=Graphics.FromImage(image)){g.Clear(Color.FromArgb(48,99,221));g.DrawString("TEST",new Font("Segoe UI",14),Brushes.White,new PointF(10,20));}image.Save(Path.Combine(dir,"000-photo.png"),ImageFormat.Png);}index.Items.Add(Item(dir,"000-photo.png","Фотографии","FAT / exFAT","Открывается"));
        for(int i=0;i<205;i++){string name="Рецепт-"+i.ToString("000")+".txt";File.WriteAllText(Path.Combine(dir,name),new string('x',i+1)+"\r\nРецепт "+i,Encoding.UTF8);index.Items.Add(Item(dir,name,"Документы",i%2==0?"NTFS":"PhotoRec",i%3==0?"Требует проверки":"Не проверялось"));}
        File.WriteAllText(Path.Combine(dir,"script.html"),"<script>throw new Error('MUST NOT RUN')</script><p>TEXT ONLY</p>");index.Items.Add(Item(dir,"script.html","Документы","PhotoRec","Не проверялось"));File.WriteAllText(Path.Combine(dir,"files-index.json"),new JavaScriptSerializer().Serialize(index),Encoding.UTF8);return dir;
    }
    static void ResultsUi(string directory)
    {
        using(var form=new RecoveryFilesForm(directory)){
            Show(form);var grid=Field<DataGridView>(form,"grid");var query=Field<TextBox>(form,"query");var method=Field<ComboBox>(form,"method");var quality=Field<ComboBox>(form,"quality");var all=Field<CheckBox>(form,"all");var selected=Field<HashSet<string>>(form,"selected");Check(grid.Rows.Count==100,"paged results default 100");Pump();Check(Field<PictureBox>(form,"previewImage").Image!=null,"verified image preview loaded");Shot(form,"UX-results");method.SelectedItem="NTFS";Pump();Check(grid.Rows.Cast<DataGridViewRow>().All(x=>((RecoveredItem)x.Tag).Method=="NTFS"),"method filter applies");quality.SelectedItem="Требует проверки";Pump();Check(grid.Rows.Cast<DataGridViewRow>().All(x=>((RecoveredItem)x.Tag).QualityLabel=="Требует проверки"),"quality filter applies");all.Checked=true;int previous=selected.Count;Check(previous>0,"select all filtered across pages");query.Text="невозможный запрос";Pump();Check(grid.Rows.Count==0&&selected.Count==previous&&!String.IsNullOrEmpty(Field<Label>(form,"feedback").Text),"empty filter state preserves selection");query.Clear();method.SelectedIndex=quality.SelectedIndex=0;Pump();Check(selected.Count==previous,"selection preserved across filter clear");
            var click=new DataGridViewCellMouseEventArgs(3,-1,0,0,new MouseEventArgs(MouseButtons.Left,1,0,0,0));typeof(DataGridView).GetMethod("OnColumnHeaderMouseClick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(grid,new object[]{click});Pump();var rows=grid.Rows.Cast<DataGridViewRow>().Select(x=>((RecoveredItem)x.Tag).Bytes).ToArray();Check(rows.SequenceEqual(rows.OrderBy(x=>x)),"numeric ascending sort");typeof(DataGridView).GetMethod("OnColumnHeaderMouseClick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(grid,new object[]{click});Pump();rows=grid.Rows.Cast<DataGridViewRow>().Select(x=>((RecoveredItem)x.Tag).Bytes).ToArray();Check(rows.SequenceEqual(rows.OrderByDescending(x=>x)),"numeric descending sort");Field<Button>(form,"next").PerformClick();Pump();long nextMaximum=((RecoveredItem)grid.Rows[0].Tag).Bytes;Check(nextMaximum<=rows.Last(),"sort order applies across pages");query.Text="Рецепт-001";Pump();Check(grid.Rows.Count==1&&Field<TextBox>(form,"previewText").Text.Contains("Рецепт 1"),"Unicode plain-text preview loaded");form.ClientSize=new Size(900,650);Pump();Check(!form.HorizontalScroll.Visible,"minimum result layout does not scroll whole window");Check(form.RectangleToClient(quality.RectangleToScreen(quality.ClientRectangle)).Right<form.ClientSize.Width,"quality filter fits minimum window");Check(form.RectangleToClient(Field<Button>(form,"stop").RectangleToScreen(Field<Button>(form,"stop").ClientRectangle)).Right<form.ClientSize.Width,"export controls fit minimum window");Shot(form,"UX-results-compact");form.Hide();
        }
        string empty=Path.Combine(root,"empty");Directory.CreateDirectory(empty);File.WriteAllText(Path.Combine(empty,"files-index.json"),new JavaScriptSerializer().Serialize(new RecoveryFileIndex()));using(var form=new RecoveryFilesForm(empty)){Show(form);Check(Field<DataGridView>(form,"grid").Rows.Count==0&&Field<Label>(form,"feedback").Text.Contains("ничего не найдено"),"empty archive truthful state");form.Hide();}
    }
    static void PreviewSafety(string directory)
    {
        var index=RecoveryCatalog.Load(directory);var html=index.Items.Single(x=>x.Name=="script.html");var result=SafeRecoveryPreview.Read(directory,html,CancellationToken.None);Check(result.Image==null&&result.Text.Contains("<script>"),"HTML remains literal text");var image=index.Items[0];result=SafeRecoveryPreview.Read(directory,image,CancellationToken.None);Check(result.Image!=null,"small raster decoded");result.Image.Dispose();bool failed=false;string hash=image.Sha256;image.Sha256=new string('0',64);try{SafeRecoveryPreview.Read(directory,image,CancellationToken.None);}catch(IOException){failed=true;}Check(failed,"SHA mismatch blocks preview");image.Sha256=hash;failed=false;using(var cancellation=new CancellationTokenSource()){cancellation.Cancel();try{SafeRecoveryPreview.Read(directory,image,cancellation.Token);}catch(OperationCanceledException){failed=true;}}Check(failed,"preview cancellation before file read");
        string bomb=Path.Combine(directory,"large-header.png");byte[] header=new byte[24];header[0]=137;header[1]=80;header[2]=78;header[3]=71;header[16]=127;header[20]=127;File.WriteAllBytes(bomb,header);result=SafeRecoveryPreview.Read(directory,Item(directory,"large-header.png","Фотографии","Synthetic","Unknown"),CancellationToken.None);Check(result.Image==null&&result.Message.Contains("лимит"),"oversize image dimensions rejected before decoder");
        string executable=Path.Combine(directory,"sample.exe");File.WriteAllText(executable,"NEVER EXECUTE");result=SafeRecoveryPreview.Read(directory,Item(directory,"sample.exe","Прочее","Synthetic","Unknown"),CancellationToken.None);Check(result.Image==null&&result.Text==null,"unsupported executable not opened");Check(Hash(Path.Combine(directory,"000-photo.png"))==hash,"source remains immutable");
    }
    static void PartialResults()
    {
        string dir=Path.Combine(root,"stopped-run");Directory.CreateDirectory(Path.Combine(dir,"files.1"));string report="{\"status\":\"cancelled\"}";File.WriteAllText(Path.Combine(dir,"result.json"),report);for(int i=0;i<16;i++)File.WriteAllText(Path.Combine(dir,"files.1","file"+i+".txt"),new string('x',1024*1024));string original=Hash(Path.Combine(dir,"files.1","file0.txt"));
        using(var form=new RecoveryForm(false)){Show(form);var pending=form.PrepareFoundFilesAsync(dir);Field<Button>(form,"stop").PerformClick();for(int poll=0;!pending.IsCompleted;poll++){if(poll>100)throw new Exception("partial catalog task timeout; busy="+form.IsBusy+" status="+Field<Label>(form,"status").Text);Pump();}Check(!pending.Result&&!form.IsBusy,"catalog preparation cancel is independent and returns idle");Check(File.ReadAllText(Path.Combine(dir,"result.json"))==report,"cancelled scan report remains cancelled");Check(Field<Button>(form,"fileList").Text=="Подготовить найденное","stopped output offers explicit catalog action");pending=form.PrepareFoundFilesAsync(dir);for(int poll=0;!pending.IsCompleted;poll++){if(poll>100)throw new Exception("partial catalog task timeout; busy="+form.IsBusy+" status="+Field<Label>(form,"status").Text);Pump();}Check(pending.Result&&RecoveryCatalog.Load(dir).Items.Count==1,"retained completed files can be indexed after cancellation (duplicates grouped)");Check(File.ReadAllText(Path.Combine(dir,"result.json"))==report&&Hash(Path.Combine(dir,"files.1","file0.txt"))==original,"preparation leaves scan status and recovered originals unchanged");form.Hide();}
    }
    [STAThread]public static int Main(string[] args)
    {
        root=Path.Combine(Path.GetFullPath(args[0]),"tests","UX-results-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss"));Directory.CreateDirectory(root);Application.SetUnhandledExceptionMode(UnhandledExceptionMode.ThrowException);Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);int code=1;var context=new ApplicationContext();
        using(var runner=new System.Windows.Forms.Timer{Interval=1}){runner.Tick+=delegate{runner.Stop();try{SetupUi();string dir=Fixtures();ResultsUi(dir);PreviewSafety(dir);PartialResults();Console.WriteLine("PASS "+checks+" UX assertions. Synthetic files only; physical discovery disabled. "+root);code=0;}catch(Exception e){Console.WriteLine("FAIL "+e);}finally{context.ExitThread();}};runner.Start();Application.Run(context);}return code;
    }
}
